83 |  */
84 | function attemptToCloseJson(json: string): string {
85 |   let result = json.trim();
86 | 
87 |   // 移除末尾可能的未完成部分
88 |   // 如果最后一个字符是逗号，移除它
89 |   if (result.endsWith(',')) {
90 |     result = result.slice(0, -1);
91 |   }
92 | 
93 |   // 统计括号
94 |   const counts = countBraces(result);
95 | 
96 |   // 如果缺少闭合引号，添加
97 |   if (counts.openQuotes % 2 !== 0) {
98 |     result = result + '"';
99 |   }
100 | 
101 |   // 闭合括号
102 |   for (let i = 0; i < counts.openBraces - counts.closeBraces; i++) {
103 |     result = result + '}';
104 |   }
105 |   for (let i = 0; i < counts.openBrackets - counts.closeBrackets; i++) {
106 |     result = result + ']';
107 |   }
108 | 
109 |   return result;
110 | }
