253 |       }
254 |       return cleaned;
255 |     };
256 | 
257 |     let currentMessages = messages.map(cleanMessage);
258 |     let continueRound = 0;
259 | 
260 |     while (continueRound <= MAX_CONTINUE_ROUNDS) {
261 |       try {
262 |         const requestBody: Record<string, unknown> = {
263 |           model: model || this.model,
