48 |  */
49 | export async function executeCommand(
50 |     input: string,
51 |     context: CommandContext
52 | ): Promise<boolean> {
53 |     const parsed = parseCommand(input);
54 | 
55 |     if (!parsed) {
56 |         return false;
57 |     }
58 | 
59 |     const { command, args } = parsed;
60 |     const handler = commands[command];
61 | 
